update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-dunkerque/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Dunkerque et sur le littoral","mecanisme":"À Dunkerque, la sidérurgie lourde, les terminaux du grand port maritime et les unités d''énergie du littoral travaillent côte à côte. Aucune de ces installations ne s''arrête vraiment. Le feu continu ne connaît ni week-end ni jour férié. Nos techniciens itinérants couvrent l''agglomération et la côte d''Opale, appuyés par le réseau national.","cta":"Demander une intervention à Dunkerque","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"24/24 et 7/7","libelle":"astreinte en option, pour les installations qui ne s''arrêtent jamais"}]},{"type":"probleme","punchline":"Une unité en feu continu s''arrête un vendredi soir sur la zone portuaire. Chaque heure se compte en production perdue, et le redémarrage coûte parfois plus que la panne.","puces":[{"accroche":"Le continu ne pardonne pas l''attente.","texte":"Sur le bassin dunkerquois, un arrêt non planifié entraîne une séquence de redémarrage longue et coûteuse."},{"accroche":"L''environnement marin attaque tout.","texte":"Sel, humidité, vent : les installations extérieures vieillissent plus vite qu''ailleurs, et la corrosion ne prévient pas."},{"accroche":"Le port impose ses accès et ses habilitations.","texte":"Un prestataire sans le cadre écrit reste au portail."},{"accroche":"Les équipements lourds usent leurs organes vite.","texte":"Machines tournantes, transmissions, hydraulique de puissance : le préventif serré coûte moins cher que la casse."},{"accroche":"Un départ de technicien, et le parc perd sa mémoire.","texte":"Sur un site lourd, l''historique vaut autant que l''outillage."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", pour les unités en service continu."},"benefice":"Une panne de nuit trouve un technicien, pas un répondeur."},{"prestation":{"accroche":"Dépannage sur site","texte":"avec recherche de cause racine, du moteur à la centrale hydraulique."},"benefice":"La ligne repart, et le défaut ne revient pas sous un autre nom."},{"prestation":{"accroche":"Préventif serré sur les équipements lourds","texte":"transmissions, alignements, équilibrage, roulements."},"benefice":"Le parc tient la cadence au lieu de décrocher machine après machine."},{"prestation":{"accroche":"Chaudronnerie, tuyauterie et soudure","texte":"sur site ou en atelier : voir la [soudure industrielle](/expertises/soudure/)."},"benefice":"Les reprises de structure se traitent sans sortir l''équipement du site."},{"prestation":{"accroche":"Cadre de sécurité écrit avant l''intervention","texte":"plan de prévention, consignation, permis de feu."},"benefice":"Vos accès portuaires et vos zones réglementées ne bloquent pas le chantier."},{"prestation":{"accroche":"Automatisme et supervision","texte":"SIEMENS et Schneider, rétrofit, roboticiens ABB et Fanuc."},"benefice":"Les installations anciennes retrouvent un pilotage fiable sans remplacement."},{"prestation":{"accroche":"Technicien en [Résidence](/offres/residence/)","texte":"intégré à votre équipe, prise de poste en 2 à 3 semaines."},"benefice":"Le poste vacant cesse d''être une fragilité, remplacement assuré."},{"prestation":{"accroche":"Arrêt technique","texte":"cadré de J-90 à J-30, restitution à la demi-journée : voir l''offre [arrêt technique](/offres/arret-technique/)."},"benefice":"Votre grand arrêt se prépare longtemps avant, et se rend à l''heure dite."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le projet. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, accès au site et au port, habilitations exigées, zones réglementées. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions horaires et d''astreinte. Aucun surcoût découvert en fin de mission."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, redémarrage sécurisé."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces, préconisations, versés dans votre GMAO."},{"titre":"Suivi","texte":"sur contrat, revue de la récurrence par équipement et du respect du plan préventif."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, habilitations vérifiées avant l''accès au site."},{"accroche":"Le cadre de sécurité précède le travail.","texte":"Sur une zone réglementée ou portuaire, rien ne commence avant le plan de prévention et la consignation."},{"accroche":"Un périmètre et une sortie écrits.","texte":"Inclus, exclu, conditions d''astreinte, conditions d''arrêt. Le cadre protège les deux parties."}]},{"type":"cta","question":"Besoin d''une astreinte réelle sur une installation qui ne s''arrête jamais ?","bouton":"Demander une intervention à Dunkerque","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-dunkerque/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Maintenance préventive et curative d''une fonderie en service continu","texte":", avec les équipes techniques du site, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Renfort habilité risque chimique sur un site de traitement des eaux industrielles","texte":", mission de 6 mois","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Un automaticien SIEMENS affecté au démarrage d''une nouvelle ligne de production","texte":", en contexte de montée en charge","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Un technicien polyvalent sur un parc machines hétérogène en forte cadence","texte":", papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Dunkerque, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence sur le littoral et nous ne l''inventons pas : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et le chargé d''affaires vous dit si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Dunkerque et les zones industrielles nord et sud, Grande-Synthe, Saint-Pol-sur-Mer, Coudekerque-Branche, Bourbourg et Gravelines, jusqu''à Calais. Au-delà, le réseau national prend le relais."},{"question":"Vos techniciens peuvent-ils accéder aux zones portuaires et réglementées ?","reponse":"Les habilitations et les autorisations exigées se vérifient à la qualification, avant le devis. Un profil sans le titre requis ne se présente pas au portail."},{"question":"Que se passe-t-il en cas de panne un dimanche ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Le circuit d''appel et l''ordre des priorités sont écrits au devis, unité par unité, avant la première urgence."},{"question":"Pouvez-vous tenir un grand arrêt programmé ?","reponse":"Oui. L''arrêt technique se cadre de J-90 à J-30 : périmètre, effectifs, séquencement, restitution à la demi-journée. La préparation fait la différence, pas l''improvisation du jour J."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable. Le diagnostic de départ est gratuit et le périmètre s''écrit équipement par équipement."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser une unité avant le prochain arrêt de campagne ?","bouton":"Demander une intervention à Dunkerque","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-dunkerque/';
